int hid_ioctl_usage(struct hiddev *hiddev, unsigned int cmd, void __user *user_arg)
{
    struct hiddev_usage_ref *urefs;
    int *usage_values;
    int i, j, error = 0;
    int count;

    switch (cmd) {
    case HIDIOCUSAGEGET:
    case HIDIOCUSAGESET:
        if (get_user(count, (int __user *)user_arg))
            return -EFAULT;

        if (count <= 0)
            return -EINVAL;

        urefs = kmalloc_array(count, sizeof(struct hiddev_usage_ref), GFP_KERNEL);
        if (!urefs)
            return -ENOMEM;

        if (copy_from_user(urefs, user_arg, count * sizeof(struct hiddev_usage_ref))) {
            kfree(urefs);
            return -EFAULT;
        }

        usage_values = kmalloc_array(count, sizeof(int), GFP_KERNEL);
        if (!usage_values) {
            kfree(urefs);
            return -ENOMEM;
        }

        for (i = 0; i < count; i++) {
            struct hid_report *report;
            struct hid_field *field;

            report = hiddev->report_enum.uses_report[urefs[i].report_type].report_id[urefs[i].report_id];
            if (!report) {
                error = -EINVAL;
                goto out;
            }

            field = report->field[urefs[i].field_index];
            if (!field || urefs[i].usage_index >= field->maxusage) {
                error = -EINVAL;
                goto out;
            }

            switch (cmd) {
            case HIDIOCUSAGEGET:
                usage_values[i] = field->usage[urefs[i].usage_index].usage;
                break;
            case HIDIOCUSAGESET:
                if (field->usage[urefs[i].usage_index].usage != 0) {
                    hid_set_field(field, urefs[i].usage_index, urefs[i].value);
                } else {
                    error = -EINVAL;
                    goto out;
                }
                break;
            }
        }

        if (copy_to_user(user_arg, usage_values, count * sizeof(int)))
            error = -EFAULT;

    out:
        kfree(urefs);
        kfree(usage_values);
        return error;
    }

    return -EINVAL;
}

