int hiddev_ioctl_usage(struct hiddev *hiddev, unsigned int cmd, void __user *user_arg)
{
    int ret = 0;
    int *usage_ref = NULL;
    struct hid_report *report;
    struct hid_field *field;
    int report_type = -1;
    int report_id = -1;
    int field_index = -1;
    int usage_index = -1;
    int value;

    switch (cmd) {
        case HIDIOCUSAGEGET:
            usage_ref = kmalloc(sizeof(int), GFP_KERNEL);
            if (!usage_ref)
                return -ENOMEM;
            if (copy_from_user(&value, user_arg, sizeof(int)))
                return -EFAULT;
            report_type = value >> 16;
            report_id = (value >> 8) & 0xff;
            field_index = (value >> 4) & 0x0f;
            usage_index = value & 0x0f;

            report = hiddev->hid->report_info[report_type].report_id_hash[report_id];
            if (!report)
                return -EINVAL;
            field = report->field[field_index];
            if (!field)
                return -EINVAL;

            if (usage_index >= field->maxusage)
                return -EINVAL;

            *usage_ref = field->usage[usage_index].usage;
            if (copy_to_user(user_arg, usage_ref, sizeof(int)))
                ret = -EFAULT;
            break;

        case HIDIOCUSAGESET:
            if (copy_from_user(&value, user_arg, sizeof(int)))
                return -EFAULT;
            report_type = value >> 16;
            report_id = (value >> 8) & 0xff;
            field_index = (value >> 4) & 0x0f;
            usage_index = value & 0x0f;

            report = hiddev->hid->report_info[report_type].report_id_hash[report_id];
            if (!report)
                return -EINVAL;
            field = report->field[field_index];
            if (!field)
                return -EINVAL;

            if (usage_index >= field->maxusage)
                return -EINVAL;

            field->usage[usage_index].usage = *usage_ref;
            break;

        default:
            ret = -EINVAL;
            break;
    }

    kfree(usage_ref);
    return ret;
}

int hiddev_ioctl_usage(struct hiddev *hiddev, unsigned int cmd, void __user *user_arg)
{
    int ret = 0;
    struct hiddev_usage *usage = NULL;
    struct hid_report *report;
    struct hid_field *field;
    struct hid_usage *usage_entry;
    int report_type, report_id, field_index, usage_code, usage_index;
    int max_usage;

    switch (cmd) {
    case HIDIOCUSAGE:
        if (copy_from_user(&usage, user_arg, sizeof(struct hiddev_usage)))
            return -EFAULT;
        break;
    default:
        return -EINVAL;
    }

    if (!usage)
        return -EFAULT;

    report_type = usage->report_type;
    report_id = usage->report_id;
    field_index = usage->field_index;
    usage_code = usage->usage_code;
    usage_index = usage->usage_index;

    report = hiddev->hid->report_enum[report_type].report_id_hash[report_id];
    if (!report)
        return -EINVAL;

    field = report->field[field_index];
    if (!field)
        return -EINVAL;

    max_usage = field->max_usage;

    if (usage_index >= max_usage)
        return -EINVAL;

    usage_entry = &field->usage[usage_index];

    if (usage_code && usage_code != usage_entry->hid) {
        return -EINVAL;
    }

    if (usage->value)
        ret = copy_from_user(&usage->value, usage->value, sizeof(__s32));
    else
        ret = -EFAULT;

    if (ret < 0)
        return ret;

    if (usage->value) {
        ret = copy_to_user(usage->value, &field->value[usage_index], sizeof(__s32));
        if (ret)
            return ret;
    }

    kfree(usage);
    return ret;
}

int hiddev_ioctl_usage(struct hiddev *hiddev, unsigned int cmd, void __user *user_arg)
{
    int ret = 0;
    struct hiddev_usage_ref *uref = NULL;
    int count = 0;
    void __user *arg = user_arg;

    uref = kmalloc(sizeof(struct hiddev_usage_ref), GFP_KERNEL);
    if (!uref)
        return -ENOMEM;

    switch (cmd) {
    case HIDIOCUSAGE:
        if (copy_from_user(uref, arg, sizeof(struct hiddev_usage_ref))) {
            ret = -EFAULT;
            break;
        }

        if (uref->report_type >= HID_REPORT_TYPES ||
            uref->report_number >= hiddev->num_reports ||
            uref->field_index >= hiddev->report[uref->report_type][uref->report_number].maxfield) {
            ret = -EINVAL;
            break;
        }

        count = hiddev->report[uref->report_type][uref->report_number].field[uref->field_index].maxusage;
        if (uref->usage_index >= count) {
            ret = -EINVAL;
            break;
        }

        uref->value = hiddev->report[uref->report_type][uref->report_number].field[uref->field_index].usage[uref->usage_index].value;
        if (copy_to_user(arg, uref, sizeof(struct hiddev_usage_ref))) {
            ret = -EFAULT;
        }
        break;

    case HIDIOCSETUSAGE:
        if (copy_from_user(uref, arg, sizeof(struct hiddev_usage_ref))) {
            ret = -EFAULT;
            break;
        }

        if (uref->report_type >= HID_REPORT_TYPES ||
            uref->report_number >= hiddev->num_reports ||
            uref->field_index >= hiddev->report[uref->report_type][uref->report_number].maxfield ||
            uref->usage_index >= hiddev->report[uref->report_type][uref->report_number].field[uref->field_index].maxusage) {
            ret = -EINVAL;
            break;
        }

        hiddev->report[uref->report_type][uref->report_number].field[uref->field_index].usage[uref->usage_index].value = uref->value;
        break;

    default:
        ret = -EINVAL;
        break;
    }

    kfree(uref);
    return ret;
}
